const R4_STATES=new Set(['desktop-calendar-search-results','desktop-filters-active','desktop-filters-collapsed','compact-calendar','compact-filters-open','compact-detail-open','tablet-calendar','tablet-calendar-search','tablet-filters-open','tablet-filters-active','tablet-detail','mobile-request-detail','mobile-calendar-search','mobile-calendar-search-results','mobile-calendar-search-empty','mobile-filters-open','mobile-filters-active','mobile-filters-empty-result','request-detail-pending','request-detail-overdue','request-detail-submitting','request-detail-success','request-detail-conflict','request-detail-alternative','request-detail-stale','request-detail-technical-error','request-detail-forbidden','mobile-request-detail-pending','mobile-request-detail-overdue','mobile-request-detail-submitting','mobile-request-detail-success','mobile-request-detail-conflict']);
const R4_RECORDS=[
  {time:'09:00',pet:'Луна',owner:'Олег Миронов',service:'Диагностика',staff:'Илья Петров',status:'Подтверждена',date:'1 августа',phone:'+7 ••• •••-22-11',tone:'success'},
  {time:'09:30',pet:'Рекс',owner:'Марина Орлова',service:'Вакцинация',staff:'Мария Смирнова',status:'Подтверждена',date:'1 августа',phone:'+7 ••• •••-42-19',tone:'success'},
  {time:'10:30',pet:'Барсик',owner:'Анна Ковалева',service:'Первичный приём терапевта',staff:'Анна Иванова',status:'Просрочена',date:'1 августа',phone:'+7 ••• •••-14-20',tone:'critical'},
  {time:'11:00',pet:'Боня',owner:'Ирина Соколова',service:'Повторный приём',staff:'Мария Смирнова',status:'Требует ответа',date:'1 августа',phone:'+7 ••• •••-88-07',tone:'warning'},
  {time:'12:00',pet:'Тоша',owner:'Дмитрий Волков',service:'Первичный приём терапевта',staff:'Илья Петров',status:'Ждёт владельца',date:'1 августа',phone:'+7 ••• •••-31-03',tone:'info'}
];
const r4State={query:'Барсик',filters:new Set(),filterDraft:new Set(),origin:'mobile-calendar-search-results',lastFocus:null};
const R5_REQUESTS=[
  {id:'barsik',priority:'critical',status:'Просрочена',tone:'critical',pet:'Барсик',service:'Терапевт',time:'10:30',deadline:'Просрочено на 02:14',nextAction:'Подтвердить или предложить другое время',owner:'Анна Ковалева',actor:'Ресепшен'},
  {id:'bonya',priority:'high',status:'Требует ответа',tone:'warning',pet:'Боня',service:'Повторный приём',time:'11:00',deadline:'Ответьте до 12:38 · через 00:38',nextAction:'Подтвердить или предложить другое время',owner:'Ирина Соколова',actor:'Ресепшен'},
  {id:'tosha',priority:'normal',status:'Ждёт владельца',tone:'info',pet:'Тоша',service:'Первичный приём',time:'12:00',deadline:'Предложено новое время: 14:30',nextAction:'Ожидается ответ владельца',owner:'Дмитрий Волков',actor:'Владелец'}
];
const r5RequestState={phase:'pending',requestId:'barsik',commandLocked:false};
function r4RestoreFocus(){const previous=r4State.lastFocus;if(!previous)return;const selector=previous.dataset.r4Go?`[data-r4-go="${CSS.escape(previous.dataset.r4Go)}"]`:previous.dataset.r4Action?`[data-r4-action="${CSS.escape(previous.dataset.r4Action)}"]`:null;const target=previous.isConnected?previous:selector?document.querySelector(selector):null;requestAnimationFrame(()=>target?.focus())}
const r4Icon=(name,label='')=>`<svg class="vh-icon" aria-hidden="true"><use href="assets/icons.svg#${name}"></use></svg>${label?`<span>${label}</span>`:''}`;
const r4Url=state=>`?${new URLSearchParams({state,role:appState.role,date:appState.date})}`;
function r4Status(record){return `<span class="vh-status" data-tone="${record.tone}"><span aria-hidden="true">${record.tone==='critical'?'!':'●'}</span>${record.status}</span>`}
function r4Results(query=r4State.query){const q=query.trim().toLocaleLowerCase('ru');return R4_RECORDS.filter(record=>!q||Object.values(record).some(value=>String(value).toLocaleLowerCase('ru').includes(q)))}
function r4CommandBarLegacy(active=0){return `<div class="vh-command" aria-label="Команды журнала"><button class="vh-date" data-r4-action="date" aria-label="Дата: 1 августа">${r4Icon('calendar','1 августа')}</button><button class="vh-search-trigger" data-r4-go="mobile-calendar-search" aria-label="Поиск по расписанию">${r4Icon('search','Поиск по расписанию')}</button><button class="vh-control" data-r4-action="filters" aria-label="Фильтры, активно ${active}">${r4Icon('filters',`Фильтры${active?` · ${active}`:''}`)}</button><button class="vh-control vh-refresh" data-r4-action="refresh" aria-label="Обновить журнал">${r4Icon('refresh','Обновить')}</button><button class="vh-primary" data-mobile-go="mobile-booking-step-client" aria-label="Новая запись">${r4Icon('create','Новая запись')}</button></div>`}
function r4NavLegacy(){return `<aside class="vh-shell-nav"><a class="vh-logo" href="${r4Url('reception-ready')}" aria-label="VetHelp"><span>V</span><strong>VetHelp</strong></a><nav aria-label="CRM разделы"><a aria-current="page" aria-label="Журнал записи" href="${r4Url('reception-ready')}">${r4Icon('calendar','Журнал записи')}</a><a aria-label="Заявки, 3 новых" href="${r4Url('mobile-request-list')}">${r4Icon('requests','Заявки')}<b>3</b></a><a aria-label="Клиенты" href="${r4Url('mobile-client-search')}">${r4Icon('clients','Клиенты')}</a><a aria-label="Ещё" href="#more">${r4Icon('more','Ещё')}</a></nav><div class="vh-location"><small>Клиника</small><strong>VetHelp Садовая</strong></div></aside>`}
function r4Chips(){return r4State.filters.size?`<div class="vh-active-chips" aria-label="Активные фильтры">${[...r4State.filters].map(label=>`<button data-r4-remove="${label}" aria-label="Убрать фильтр ${label}">${label} ${r4Icon('close')}</button>`).join('')}</div>`:''}
function r4Record(record){return `<button class="vh-record" data-r4-record="${record.pet}"><span class="vh-record-time">${record.time}</span><span><strong>${record.pet}</strong><small>${record.service}</small><small>${record.staff}</small></span>${r4Status(record)}</button>`}
function r4Calendar(){return `<section class="vh-calendar" aria-label="Расписание"><div class="vh-calendar-head"><strong>08:00–20:00</strong><span>Анна Иванова</span><span>Илья Петров</span><span>Мария Смирнова</span></div><div class="vh-calendar-body">${R4_RECORDS.map(r4Record).join('')}</div></section>`}
function r4FilterForm(){const options={Сотрудники:['Анна Иванова','Илья Петров','Мария Смирнова'],Услуги:['Первичный приём','Диагностика','Вакцинация'],Статусы:['Подтверждена','Требует ответа','Просрочена']};return `<div class="vh-filter-groups">${Object.entries(options).map(([title,values])=>`<fieldset><legend>${title}</legend>${values.map(value=>`<label><input type="checkbox" value="${value}" ${r4State.filterDraft.has(value)?'checked':''}><span>${value}</span></label>`).join('')}</fieldset>`).join('')}<label class="vh-action-only"><input type="checkbox" value="Только требуют действия" ${r4State.filterDraft.has('Только требуют действия')?'checked':''}><span>Только требуют действия</span></label></div>`}
function r4Filters(mode='overlay'){return `<section class="vh-filters ${mode==='rail'?'is-rail':'is-overlay'}" ${mode==='rail'?'':'role="dialog" aria-modal="true"'} aria-labelledby="vh-filters-title"><header><button class="vh-back" data-r4-action="close-filters" aria-label="Назад">${r4Icon('back')}</button><h2 id="vh-filters-title" tabindex="-1">Фильтры</h2></header>${r4FilterForm()}<footer><button class="vh-secondary" data-r4-action="reset-filters">Сбросить</button><button class="vh-primary" data-r4-action="apply-filters">Показать ${r4State.filterDraft.size?8:14} записей</button></footer></section>`}
function r4Search(empty=false){const results=empty?[]:r4Results();return `<main class="vh-task" data-task="search"><header><button class="vh-back" data-r4-action="close-search" aria-label="Назад">${r4Icon('back')}</button><h1 tabindex="-1">Поиск по расписанию</h1></header><label class="vh-search-field"><span>Поиск по расписанию</span><span class="vh-input-wrap">${r4Icon('search')}<input id="vh-search-input" type="search" value="${empty?'Черепаха':r4State.query}" placeholder="Поиск по расписанию" autocomplete="off"><button data-r4-action="clear-search" aria-label="Очистить поиск">${r4Icon('close')}</button></span></label><p class="vh-search-progress" role="status" hidden>Ищем записи…</p><section class="vh-search-results" aria-live="polite"><h2>${r4State.query?'Результаты':'Недавние'}</h2>${results.length?results.map(record=>`<button class="vh-search-result" data-r4-record="${record.pet}"><span class="vh-record-time">${record.time}</span><span><strong>${record.pet}</strong><small>${record.date} · ${record.service}</small><small>${record.staff}</small></span>${r4Status(record)}</button>`).join(''):'<div class="vh-empty"><h3>Ничего не найдено</h3><p>Измените запрос или сбросьте фильтры.</p></div>'}</section></main>`}
function r4DetailLegacy(){const record=R4_RECORDS[2];return `<main class="vh-task" data-task="detail"><header><button class="vh-back" data-r4-action="detail-back" aria-label="Назад">${r4Icon('back')}</button><h1 tabindex="-1">Карточка записи</h1><button class="vh-close" data-r4-action="detail-close" aria-label="Закрыть">${r4Icon('close')}</button></header><section class="vh-detail"><div>${r4Status(record)}<h2>${record.pet}</h2><p>${record.service}</p></div><dl><div><dt>Время</dt><dd>10:30–11:00</dd></div><div><dt>Сотрудник</dt><dd>${record.staff}</dd></div><div><dt>Владелец</dt><dd>${record.owner}</dd></div><div><dt>Телефон</dt><dd>${record.phone}</dd></div><div><dt>Цена</dt><dd>2 500 ₽</dd></div></dl></section><footer class="vh-task-actions"><button class="vh-primary">Подтвердить</button><button class="vh-secondary">Другое время</button></footer></main>`}
function r4WorkspaceLegacy(state){const filtersActive=state.includes('filters-active'),filtersOpen=state.includes('filters-open'),collapsed=state==='desktop-filters-collapsed',detail=state.includes('detail'),search=state.includes('search');if(filtersActive&&!r4State.filters.size){r4State.filters=new Set(['Анна Иванова','Требует ответа']);r4State.filterDraft=new Set(r4State.filters)}return `<div class="vh-responsive-shell">${r4Nav()}<main class="vh-workspace"><header class="vh-topbar"><div><small>VetHelp Садовая</small><h1>Журнал записи</h1></div>${r4CommandBar(r4State.filters.size)}</header><section class="vh-sla"><div><span class="vh-status" data-tone="critical"><span aria-hidden="true">!</span>Просрочена</span><strong>1 заявка требует немедленного ответа</strong></div><button class="vh-primary" data-r4-record="Барсик">Открыть заявку</button></section>${r4Chips()}<div class="vh-work-area">${collapsed?'<button class="vh-collapsed-filter" data-r4-action="filters" aria-label="Фильтры, активно 2">'+r4Icon('filters')+'<b>2</b></button>':innerWidth>=1280?r4Filters('rail'):''}${r4Calendar()}</div></main>${filtersOpen?r4Filters('overlay'):''}${search?r4Search(false):''}${detail?r4Detail():''}</div>`}
function renderR4Legacy(state){let surface=document.getElementById('r4-surface');if(!surface){surface=document.createElement('div');surface.id='r4-surface';document.body.append(surface)}document.body.classList.toggle('r4-active',R4_STATES.has(state));if(!R4_STATES.has(state)){surface.replaceChildren();decorateCRM();return}surface.innerHTML=state.startsWith('mobile-calendar-search')?r4Search(state.endsWith('empty')):state.startsWith('mobile-filters')?`<div class="vh-mobile-shell">${r4Filters('overlay')}${state!=='mobile-filters-open'?r4Chips():''}${state==='mobile-filters-empty-result'?'<div class="vh-empty"><h3>Нет записей</h3><p>Сбросьте один или несколько фильтров.</p></div>':''}</div>`:r4Workspace(state);requestAnimationFrame(()=>surface.querySelector('[role=dialog] h2,.vh-task h1')?.focus());decorateCRM()}
function r4Go(state,{replace=false}={}){const url=r4Url(state);history[replace?'replaceState':'pushState'](null,'',url);appState.state=state;app.dataset.state=state;if(typeof MOBILE_STATES!=='undefined'&&MOBILE_STATES.has(state))renderMobileCRM(state);renderR4(state);scrollTo(0,0)}
function decorateCRM(){document.documentElement.dataset.vhDesign='unified';document.querySelectorAll('.sidebar nav a').forEach((link,index)=>{const names=['calendar','requests','clients','staff','settings'];const text=link.childNodes[link.childNodes.length-1]?.textContent?.trim()||link.textContent.trim();const count=link.querySelector('.nav-count')?.outerHTML||'';link.innerHTML=`${r4Icon(names[index]||'more')}<span>${text.replace(/\d+$/,'').trim()}</span>${count}`});const mobileRoot=document.getElementById('mobile-crm');if(!mobileRoot?.hidden&&!mobileRoot.querySelector('.vh-mobile-command')){const anchor=mobileRoot.querySelector('.m-date-strip')||mobileRoot.querySelector('.m-appbar');anchor?.insertAdjacentHTML('afterend',`<div class="vh-mobile-command"><button data-r4-go="mobile-calendar-search">${r4Icon('search','Поиск по расписанию')}</button><button data-r4-action="filters" aria-label="Фильтры, активно ${r4State.filters.size}">${r4Icon('filters',`Фильтры${r4State.filters.size?` · ${r4State.filters.size}`:''}`)}</button><button class="vh-primary" data-mobile-go="mobile-booking-step-client" aria-label="Новая запись">${r4Icon('create')}</button></div>`)}if(app.dataset.state==='mobile-request-detail'&&r4State.origin.startsWith('mobile-calendar-search')){const back=mobileRoot.querySelector('.m-back');if(back){back.dataset.r4Go=r4State.origin;delete back.dataset.mobileGo}}}
function decorateIcons(){const controls=[['[data-action=previous-day]','previous',''],['[data-action=next-day]','next',''],['[data-action=open-search]','search','Поиск'],['[data-action=refresh]','refresh','Обновить'],['[data-action=open-filters]','filters','Фильтры'],['[data-action=manual-booking]','create','Новая запись'],['[data-action=close-drawer]','close',''],['[data-action=close-modal]','close',''],['[data-action=close-search]','close',''],['[data-action=close-filters]','back','']];for(const[selector,icon,label]of controls)document.querySelectorAll(selector).forEach(button=>{if(!button.querySelector('.vh-icon'))button.innerHTML=r4Icon(icon,label)});const date=document.querySelector('.date-button');if(date&&!date.querySelector('.vh-icon'))date.insertAdjacentHTML('afterbegin',r4Icon('calendar'));document.querySelectorAll('.mobile-crm-nav button').forEach((button,index)=>{const names=['calendar','requests','clients','more'];if(!button.querySelector('.vh-icon'))button.querySelector('span')?.replaceWith(document.createRange().createContextualFragment(r4Icon(names[index])))})}
document.addEventListener('click',event=>{const go=event.target.closest('[data-r4-go]');if(go){event.preventDefault();r4State.lastFocus=go;r4Go(go.dataset.r4Go);return}const record=event.target.closest('[data-r4-record]');if(record){event.preventDefault();r4State.origin=new URLSearchParams(location.search).get('state')||'mobile-calendar-search-results';r4Go(innerWidth<600?'mobile-request-detail':'compact-detail-open');return}const remove=event.target.closest('[data-r4-remove]');if(remove){r4State.filters.delete(remove.dataset.r4Remove);r4State.filterDraft=new Set(r4State.filters);renderR4(new URLSearchParams(location.search).get('state'));return}const action=event.target.closest('[data-r4-action]');if(!action)return;const name=action.dataset.r4Action;if(name==='filters'){r4State.lastFocus=action;r4State.filterDraft=new Set(r4State.filters);r4Go(innerWidth<600?'mobile-filters-open':'tablet-filters-open')}else if(name==='apply-filters'){r4State.filters=new Set([...document.querySelectorAll('.vh-filters input:checked')].map(input=>input.value));r4Go(innerWidth<600?'mobile-filters-active':'tablet-filters-active')}else if(name==='reset-filters'){r4State.filters.clear();r4State.filterDraft.clear();document.querySelectorAll('.vh-filters input').forEach(input=>input.checked=false)}else if(name==='close-filters'){history.back()}else if(name==='close-search'){history.back()}else if(name==='clear-search'){r4State.query='';r4Go('mobile-calendar-search',{replace:true})}else if(name==='detail-back'){r4Go(r4State.origin)}else if(name==='detail-close'){r4Go(innerWidth<600?'mobile-today':'compact-calendar')}else if(name==='refresh')announce('Журнал обновлён в 14:34')},true);
document.addEventListener('input',event=>{if(event.target.id!=='vh-search-input')return;r4State.query=event.target.value;const progress=document.querySelector('.vh-search-progress');if(progress)progress.hidden=false;clearTimeout(r4State.timer);r4State.timer=setTimeout(()=>r4Go(r4State.query.trim()?'mobile-calendar-search-results':'mobile-calendar-search',{replace:true}),180)});
document.addEventListener('change',event=>{if(!event.target.matches('.vh-filters input'))return;r4State.filterDraft=new Set([...document.querySelectorAll('.vh-filters input:checked')].map(input=>input.value));const apply=document.querySelector('.vh-filters [data-r4-action=apply-filters]');if(apply)apply.textContent=`Показать ${r4State.filterDraft.size?8:14} записей`;announce(`Выбрано фильтров: ${r4State.filterDraft.size}`)});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&R4_STATES.has(new URLSearchParams(location.search).get('state'))){event.preventDefault();history.back()}});
function r4CloseOverlay(){const returnState=r4State.returnState||(innerWidth<600?'mobile-today':'compact-calendar');r4Go(returnState,{replace:true});r4RestoreFocus()}
window.addEventListener('click',event=>{const go=event.target.closest('[data-r4-go]');if(go&&go.dataset.r4Go.startsWith('mobile-calendar-search')){event.preventDefault();event.stopImmediatePropagation();r4State.returnState=new URLSearchParams(location.search).get('state')||'mobile-today';r4State.lastFocus=go;r4Go(go.dataset.r4Go);return}const action=event.target.closest('[data-r4-action]');if(!action)return;if(action.dataset.r4Action==='filters'){event.preventDefault();event.stopImmediatePropagation();r4State.returnState=new URLSearchParams(location.search).get('state')||(innerWidth<600?'mobile-today':'compact-calendar');r4State.lastFocus=action;r4State.filterDraft=new Set(r4State.filters);r4Go(innerWidth<600?'mobile-filters-open':'tablet-filters-open')}else if(['close-filters','close-search'].includes(action.dataset.r4Action)){event.preventDefault();event.stopImmediatePropagation();r4CloseOverlay()}},true);
window.addEventListener('keydown',event=>{if(event.key==='Escape'&&R4_STATES.has(new URLSearchParams(location.search).get('state'))){event.preventDefault();event.stopImmediatePropagation();r4CloseOverlay()}},true);
window.addEventListener('click',event=>{const opener=event.target.closest('[data-r5-open]');if(opener){event.preventDefault();event.stopImmediatePropagation();r4State.lastFocus=opener;r4State.origin=new URLSearchParams(location.search).get('state')||'request-overdue';r5RequestState.requestId=opener.dataset.r5Open;r4Go(innerWidth<600?'mobile-request-detail-overdue':'request-detail-overdue');return}const action=event.target.closest('[data-r5-action]');if(!action)return;event.preventDefault();event.stopImmediatePropagation();if(action.dataset.r5Action==='confirm'&&!r5RequestState.commandLocked){r5RequestState.commandLocked=true;r4Go(innerWidth<600?'mobile-request-detail-submitting':'request-detail-submitting',{replace:true});setTimeout(()=>{r5RequestState.commandLocked=false;r4Go(innerWidth<600?'mobile-request-detail-success':'request-detail-success',{replace:true})},120)}else if(action.dataset.r5Action==='alternative'&&!r5RequestState.commandLocked){r4Go('request-detail-alternative',{replace:true})}else if(action.dataset.r5Action==='refresh-conflict'){r4Go('request-detail-pending',{replace:true});requestAnimationFrame(()=>{const heading=document.querySelector('.vh-request-detail h1');heading?.focus();document.querySelector('.vh-request-detail')?.setAttribute('data-refreshed','true')})}},true);
window.addEventListener('popstate',()=>{renderR4(new URLSearchParams(location.search).get('state')||'reception-ready');r4RestoreFocus()});
new MutationObserver(()=>queueMicrotask(()=>{decorateCRM();decorateIcons()})).observe(document.getElementById('mobile-crm'),{childList:true,subtree:false});
decorateIcons();

const R5_SHELL_STATES=new Set(['reception-ready','admin-ready','veterinarian-limited','multi-role-ready','pending-request','request-overdue','week-view','week-alternative-selection']);
function r5Role(){return VH_ROLE_PRESENTATION[appState.role]||VH_ROLE_PRESENTATION.reception}
function r5Can(key){return r5Role().capabilities.has(key)}
function r5View(state){return state.includes('week')?'week':['pending-request','request-overdue'].includes(state)?'list':'day'}
function r5ViewSwitch(active){return `<div class="vh-view-switch" aria-label="Представление журнала">${[['day','День'],['week','Неделя'],['list','Список']].map(([view,label])=>`<button data-r5-view="${view}" aria-pressed="${view===active}">${label}</button>`).join('')}</div>`}
function r4CommandBar(active=0,view='day'){return `<div class="vh-header-tools"><div class="vh-date-navigation" aria-label="Навигация по датам"><button class="vh-control" aria-label="Предыдущий день">${r4Icon('previous')}</button><button class="vh-date" data-r4-action="date" aria-label="Сегодня, 1 августа">Сегодня · 1 августа 2026</button><button class="vh-control" aria-label="Следующий день">${r4Icon('next')}</button></div>${r5ViewSwitch(view)}<div class="vh-command" aria-label="Команды журнала"><button class="vh-search-trigger" data-r4-go="mobile-calendar-search" aria-label="Поиск по расписанию">${r4Icon('search','Поиск')}</button>${r5Can('booking.request.read')?`<button class="vh-control" data-r4-action="filters" aria-label="Фильтры, активно ${active}">${r4Icon('filters',`Фильтры${active?` · ${active}`:''}`)}</button>`:''}<button class="vh-control vh-refresh" data-r4-action="refresh" aria-label="Обновить журнал">${r4Icon('refresh','Обновить')}</button>${r5Can('booking.create')?`<button class="vh-primary" data-mobile-go="mobile-booking-step-client" aria-label="Новая запись">${r4Icon('create','Новая запись')}</button>`:''}</div></div>`}
function r4Nav(){const role=r5Role(),items=role.activeWorkspace==='veterinarian'?[['calendar','Мой день','reception-ready'],['requests','Мои визиты','pending-request']]:[['calendar','Журнал','reception-ready'],['requests','Заявки','mobile-request-list'],['clients','Клиенты','mobile-client-search']];if(r5Can('clinic.staff.read'))items.push(['staff','Сотрудники','admin-ready']);if(r5Can('clinic.settings.read'))items.push(['settings','Настройки','admin-ready']);return `<aside class="vh-shell-nav"><a class="vh-logo" href="${r4Url('reception-ready')}" aria-label="VetHelp"><span>V</span><strong>VetHelp</strong></a><nav aria-label="CRM разделы">${items.map(([icon,label,state],index)=>`<a ${index?'':'aria-current="page"'} aria-label="${label}" href="${r4Url(state)}">${r4Icon(icon,label)}${label==='Заявки'?'<b>3</b>':''}</a>`).join('')}</nav><div class="vh-location"><small>Клиника</small><strong>VetHelp Садовая</strong></div></aside>`}
function r5PhaseFromState(state){if(state.includes('submitting'))return'submitting';if(state.includes('success'))return'success';if(state.includes('conflict'))return'conflict';if(state.includes('alternative'))return'alternative';if(state.includes('stale'))return'stale';if(state.includes('technical-error'))return'technical-error';if(state.includes('forbidden'))return'forbidden';if(state.includes('overdue'))return'overdue';return'pending'}
function r5Summary(state){if(state==='reception-ready')return `<section class="vh-sla vh-sla-clear" data-summary="clear"><div><strong>Все заявки обработаны</strong><span>Новых решений сейчас нет</span></div></section>`;if(state==='pending-request')return `<section class="vh-sla vh-sla-pending" data-summary="pending"><div><strong>3 заявки требуют ответа</strong><span>Ближайший срок — через 08:42</span></div><button class="vh-primary" data-r5-open="bonya" aria-label="Открыть следующую заявку Бони">Открыть следующую</button></section>`;return `<section class="vh-sla vh-sla-critical" data-summary="overdue"><div class="vh-sla-main"><span class="vh-status" data-tone="critical"><span aria-hidden="true">!</span>Просрочена 1 заявка</span><strong>Барсик · Терапевт · 10:30</strong><span>Просрочено на 02:14</span><button class="vh-primary" data-r5-open="barsik" aria-label="Открыть просроченную заявку Барсика">Открыть заявку</button></div><div class="vh-sla-secondary"><span>Следующая истекает через 00:38</span><span>Ещё 2 требуют ответа</span></div></section>`}
function r5RequestQueue(){return `<section class="vh-request-queue" aria-labelledby="request-queue-title"><header><div><span>Очередь решений</span><h2 id="request-queue-title">Сначала требующие внимания</h2></div><small>Порядок показан только для UX-прототипа</small></header>${R5_REQUESTS.map((request,index)=>`<button class="vh-request-row" data-r5-open="${request.id}" data-priority="${request.priority}" aria-label="${request.pet}, ${request.status}, ${request.deadline}"><b class="vh-order">${index+1}</b><span>${r4Status(request)}<strong>${request.pet}</strong><small>${request.service} · ${request.time}</small></span><span class="vh-request-deadline">${request.deadline}</span><span class="vh-request-next"><small>Следующее действие · ${request.actor}</small><strong>${request.nextAction}</strong></span></button>`).join('')}</section>`}
function r4Detail(state=new URLSearchParams(location.search).get('state')||'request-detail-overdue'){const canDecide=r5Can('booking.request.decide'),phase=r5PhaseFromState(state),request=R5_REQUESTS.find(item=>item.id===r5RequestState.requestId)||R5_REQUESTS[0],readonly=!canDecide,alternative=phase==='alternative',success=phase==='success',locked=phase==='submitting'||alternative||success||readonly;const status=readonly?'Назначенный визит':success?'Подтверждена':alternative?'Ждёт владельца':phase==='overdue'?'Просрочена':'Требует ответа';const tone=success?'success':alternative?'info':phase==='overdue'?'critical':'warning';const warning=phase==='conflict'?'<section class="vh-context-warning" data-command-state="conflict"><strong>Заявка уже изменилась</strong><p>Другой сотрудник обработал её или владелец изменил запись. Обновите данные, чтобы увидеть актуальное состояние.</p><button class="vh-secondary" data-r5-action="refresh-conflict">Обновить</button></section>':phase==='stale'?'<section class="vh-context-warning" data-command-state="stale"><strong>Данные могли устареть</strong><p>Контекст заявки сохранён. Обновите данные перед решением.</p><button class="vh-secondary" data-r5-action="refresh-conflict">Обновить</button></section>':phase==='technical-error'?'<section class="vh-context-warning" data-command-state="technical-error"><strong>Не удалось обновить заявку</strong><p>Это техническая ошибка. Данные заявки сохранены.</p><button class="vh-secondary" data-r5-action="refresh-conflict">Повторить</button></section>':phase==='forbidden'?'<section class="vh-context-warning" data-command-state="forbidden"><strong>Недостаточно прав для решения</strong><p>Заявка остаётся доступна только для чтения.</p></section>':'';const nextTitle=readonly?'Контекст визита':success?'Действие принято':alternative?'Ожидается ответ владельца':'Следующее действие';const nextCopy=readonly?'Административное решение принимает ресепшен.':success?'Статус обновлён по результату readback: запись подтверждена.':alternative?'Предложено новое время: 14:30. Решение владельца ещё не получено.':'Клиника ещё не подтвердила выбранное время. Подтвердите его или предложите владельцу альтернативу.';return `<main class="vh-task vh-request-detail" data-task="detail" data-command-state="${phase}" data-role-mode="${r5Role().activeWorkspace}"><header><button class="vh-back" data-r4-action="detail-back" aria-label="Назад">${r4Icon('back')}</button><div><span class="vh-status" data-tone="${tone}"><span aria-hidden="true">${tone==='critical'?'!':'●'}</span>${status}</span><h1 tabindex="-1">${readonly?'Назначенный визит':'Заявка на приём'}</h1><p>${request.deadline}</p></div><button class="vh-close" data-r4-action="detail-close" aria-label="Закрыть заявку">${r4Icon('close')}</button></header>${warning}<section class="vh-next-action" aria-labelledby="next-action-title"><span class="vh-priority" data-priority="${request.priority}">${request.priority==='critical'?'Критический приоритет':request.priority==='high'?'Высокий приоритет':'Обычный приоритет'}</span><h2 id="next-action-title">${nextTitle}</h2><p>${nextCopy}</p>${phase==='submitting'?'<button class="vh-primary" disabled aria-busy="true">Подтверждаем…</button>':''}</section><section class="vh-request-facts"><h2>Клиент и питомец</h2><dl><div><dt>Питомец</dt><dd>${request.pet}</dd></div><div><dt>Владелец</dt><dd>${request.owner}</dd></div><div><dt>Желаемое время</dt><dd>1 августа · ${request.time}</dd></div><div><dt>Услуга</dt><dd>${request.service}</dd></div></dl></section><section class="vh-activity"><h2>Недавняя активность</h2><ol><li><span aria-hidden="true">●</span><div><strong>Заявка создана</strong><small>Владелец · 10:02</small></div></li><li><span aria-hidden="true">●</span><div><strong>Открыта сотрудником</strong><small>Анна Смирнова · 10:07</small></div></li>${alternative?'<li><span aria-hidden="true">●</span><div><strong>Предложено другое время</strong><small>Анна Смирнова · 10:11 · 14:30 вместо 12:00</small></div></li>':''}</ol></section>${!readonly&&!locked&&phase!=='conflict'?'<section class="vh-destructive"><button data-r5-action="reject" aria-label="Отклонить заявку Барсика">Отклонить заявку</button></section>':''}<p class="sr-only" aria-live="polite" data-r5-live>${success?'Действие принято. Заявка подтверждена.':alternative?'Предложено другое время. Ожидается ответ владельца.':''}</p>${!readonly&&!locked&&phase!=='conflict'?`<footer class="vh-task-actions"><button class="vh-primary" data-r5-action="confirm">Подтвердить</button><button class="vh-secondary" data-r5-action="alternative">Другое время</button></footer>`:''}</main>`}
function r4Workspace(state){const filtersActive=state.includes('filters-active'),filtersOpen=state.includes('filters-open'),collapsed=state==='desktop-filters-collapsed',detail=state.includes('detail')||['pending-request','request-overdue'].includes(state),search=state.includes('search'),view=r5View(state),role=r5Role(),queue=['pending-request','request-overdue','reception-ready'].includes(state)&&role.activeWorkspace!=='veterinarian';if(filtersActive&&!r4State.filters.size){r4State.filters=new Set(['Анна Иванова','Требует ответа']);r4State.filterDraft=new Set(r4State.filters)}const title=role.activeWorkspace==='veterinarian'?'Мой день':'Журнал записи';return `<div class="vh-responsive-shell" data-state="${state}" data-role="${role.role}" data-workspace="${role.activeWorkspace}">${r4Nav()}<main class="vh-workspace"><header class="vh-topbar"><div><small>VetHelp · Садовая</small><h1>${title}</h1>${role.role==='multi-role'?'<span class="vh-role-context">Режим: Ресепшен</span>':role.role==='admin'?'<span class="vh-role-context">Режим: Управление</span>':''}</div>${r4CommandBar(r4State.filters.size,view)}</header>${role.activeWorkspace==='veterinarian'?'<section class="vh-workspace-note"><strong>Мои назначенные визиты</strong><span>Только безопасный контекст вашего рабочего дня</span></section>':r5Summary(state)}${r4Chips()}<div class="vh-work-area">${collapsed?'<button class="vh-collapsed-filter" data-r4-action="filters" aria-label="Фильтры, активно 2">'+r4Icon('filters')+'<b>2</b></button>':innerWidth>=1280&&r5Can('booking.request.read')&&!queue?r4Filters('rail'):''}<div class="vh-view-surface" data-view="${view}">${queue?r5RequestQueue():r4Calendar()}</div></div></main>${filtersOpen?r4Filters('overlay'):''}${search?r4Search(false):''}${detail?r4Detail(state):''}</div>`}
function renderR4(state){let surface=document.getElementById('r4-surface');if(!surface){surface=document.createElement('div');surface.id='r4-surface';document.body.append(surface)}const shellState=R4_STATES.has(state)||(innerWidth>=600&&R5_SHELL_STATES.has(state));document.body.classList.toggle('r4-active',shellState);if(!shellState){surface.replaceChildren();decorateCRM();applyRolePresentation();return}if(state==='mobile-calendar-search')r4State.query='';else if(state==='mobile-calendar-search-results')r4State.query='Барсик';if(state==='mobile-filters-active'&&!r4State.filters.size){r4State.filters=new Set(['Анна Иванова','Требует ответа']);r4State.filterDraft=new Set(r4State.filters)}surface.innerHTML=state.startsWith('mobile-calendar-search')?r4Search(state.endsWith('empty')):state.startsWith('mobile-filters')?`<div class="vh-mobile-shell" data-state="${state}">${r4Filters('overlay')}${state!=='mobile-filters-open'?r4Chips():''}${state==='mobile-filters-empty-result'?'<div class="vh-empty"><h3>Нет записей</h3><p>Сбросьте один или несколько фильтров.</p></div>':''}</div>`:r4Workspace(state);requestAnimationFrame(()=>surface.querySelector('[role=dialog] h2,.vh-task h1')?.focus());decorateCRM();applyRolePresentation()}
function applyRolePresentation(){const role=r5Role(),mobile=document.getElementById('mobile-crm'),nav=document.querySelector('.mobile-crm-nav');document.documentElement.dataset.vhRole=role.role;if(!mobile||mobile.hidden)return;const existing=mobile.querySelector('.vh-role-context'),needsMarker=['admin','multi-role','veterinarian'].includes(role.role),markerText=`Режим: ${role.workspaceLabel}`;if(needsMarker&&!existing){const marker=document.createElement('div');marker.className='vh-role-context vh-role-context-mobile';marker.textContent=markerText;mobile.querySelector('.m-appbar')?.insertAdjacentElement('afterend',marker)}else if(needsMarker&&existing.textContent!==markerText)existing.textContent=markerText;else if(!needsMarker)existing?.remove();if(role.activeWorkspace==='veterinarian'){mobile.querySelectorAll('[data-mobile-go^="mobile-booking"],[data-mobile-action="confirm"],[data-mobile-go="mobile-alternative-date"],[data-mobile-action="reject-menu"],.vh-mobile-command [data-r4-action="filters"],.vh-mobile-command .vh-primary').forEach(node=>node.remove());const visits=nav?.querySelector('[data-mobile-nav="mobile-request-list"] strong');if(visits&&visits.textContent!=='Мои визиты')visits.textContent='Мои визиты';nav?.querySelector('[data-mobile-nav="mobile-client-search"]')?.remove();nav?.querySelector('[data-mobile-nav="mobile-more"]')?.remove()}else if(role.role==='admin'){const more=nav?.querySelector('[data-mobile-nav="mobile-more"] strong');if(more&&more.textContent!=='Управление')more.textContent='Управление'}}
document.addEventListener('click',event=>{const view=event.target.closest('[data-r5-view]');if(!view)return;event.preventDefault();const target={day:'reception-ready',week:'week-view',list:'pending-request'}[view.dataset.r5View];r4Go(target)});
new MutationObserver(()=>queueMicrotask(applyRolePresentation)).observe(document.getElementById('mobile-crm'),{childList:true,subtree:false});
renderR4(new URLSearchParams(location.search).get('state')||'reception-ready');
function applyR5DetailRoleContext(){const detail=document.querySelector('.vh-request-detail'),role=r5Role();if(!detail)return;const phase=detail.dataset.commandState,protectedCopy={forbidden:['Решение недоступно','У вашей роли нет права обработать эту заявку. Контекст доступен только для чтения.'],stale:['Сначала обновите данные','Решения заблокированы, пока не получена актуальная версия заявки.'],"technical-error":['Сначала восстановите данные','Решения заблокированы до успешного обновления заявки.']};if(protectedCopy[phase]){detail.querySelector('.vh-task-actions')?.remove();detail.querySelector('.vh-destructive')?.remove();const [title,copy]=protectedCopy[phase],section=detail.querySelector('.vh-next-action');if(section){section.querySelector('h2').textContent=title;section.querySelector('p').textContent=copy}detail.dataset.decisionLocked='true'}const current=detail.querySelector('.vh-role-context');if(!['admin','multi-role'].includes(role.role)){current?.remove();return}const label=role.role==='admin'?'Режим: Управление':'Режим: Ресепшен';if(current){current.textContent=label;return}const marker=document.createElement('span');marker.className='vh-role-context';marker.textContent=label;detail.querySelector('header>div h1')?.insertAdjacentElement('beforebegin',marker)}
const r5Surface=document.getElementById('r4-surface');
if(r5Surface)new MutationObserver(()=>queueMicrotask(applyR5DetailRoleContext)).observe(r5Surface,{childList:true});
applyR5DetailRoleContext();
